1161→// gitCommitStagedWithShadowHooks is the shared implementation for committing staged changes with hooks.
1162→func (env *TestEnv) gitCommitStagedWithShadowHooks(message string, simulateTTY bool) {
1163→	env.T.Helper()
1164→
1165→	// Create a temp file for the commit message (prepare-commit-msg hook modifies this)
1166→	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
1167→	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
1168→		env.T.Fatalf("failed to write commit message file: %v", err)
1169→	}
1170→
1171→	// Run prepare-commit-msg hook using the shared binary.
1172→	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile, "message")
1173→	prepCmd.Dir = env.RepoDir
1174→	if simulateTTY {
1175→		prepCmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=1")
1176→	} else {
1177→		prepCmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
1178→	}
1179→	if output, err := prepCmd.CombinedOutput(); err != nil {
1180→		env.T.Logf("prepare-commit-msg output: %s", output)
1181→	}
1182→
1183→	// Read the modified message
1184→	modifiedMsg, err := os.ReadFile(msgFile)
1185→	if err != nil {
1186→		env.T.Fatalf("failed to read modified commit message: %v", err)
1187→	}
1188→
1189→	// Create the commit using go-git with the modified message
1190→	repo, err := git.PlainOpen(env.RepoDir)
1191→	if err != nil {
1192→		env.T.Fatalf("failed to open git repo: %v", err)
1193→	}
1194→
1195→	worktree, err := repo.Worktree()
1196→	if err != nil {
1197→		env.T.Fatalf("failed to get worktree: %v", err)
1198→	}
1199→
1200→	_, err = worktree.Commit(string(modifiedMsg), &git.CommitOptions{
1201→		Author: &object.Signature{
1202→			Name:  "Test User",
1203→			Email: "test@example.com",
1204→			When:  time.Now(),
1205→		},
1206→	})
1207→	if err != nil {
1208→		env.T.Fatalf("failed to commit: %v", err)
1209→	}
1210→
1211→	// Run post-commit hook
1212→	postCmd := exec.Command(getTestBinary(), "hooks", "git", "post-commit")
1213→	postCmd.Dir = env.RepoDir
1214→	if output, err := postCmd.CombinedOutput(); err != nil {
1215→		env.T.Logf("post-commit output: %s", output)
1216→	}
1217→}
